window.STORY_CHAPTERS["c94105f8426aa4559"]={"id":"c94105f8426aa4559","lines":[{"uid":"talk.ch18_5_4101#originalText","id":"talk.ch18_5_4101","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"应该……赶上了吧？","en":"You think that was in time?","ja":"間に合った……ッスかね"},"kind":"dialogue"},{"uid":"talk.ch18_5_4102#originalText","id":"talk.ch18_5_4102","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"一定能赶上的。","en":"It was in time. Definitely.","ja":"間に合ったわ、絶対"},"kind":"dialogue"},{"uid":"talk.ch18_5_4103#originalText","id":"talk.ch18_5_4103","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"真是的……我实在太大意了……","en":"Seriously, I can't believe I was so careless.","ja":"まったく……我ながら迂闊すぎたッスよ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4104#originalText","id":"talk.ch18_5_4104","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"没想到敌方居然会让美国的VRMMO玩家潜行到Underworld。","en":"Who knew that they'd have American VRMMO players dive into the Underworld?","ja":"まさか相手さんが、アメリカのVRMMOプレイヤーをアンダーワールドにダイブさせてくるなんて"},"kind":"dialogue"},{"uid":"talk.ch18_5_4105#originalText","id":"talk.ch18_5_4105","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"而且察觉这一点的，是明日奈小姐的手机所联结的既有型AI。","en":"Not only that, but it was an existing AI connected to Asuna's cell phone that detected it.","ja":"しかもその動きを察知したのが、明日奈さんの端末に接続していた既存型のAIだっていうんですから"},"kind":"dialogue"},{"uid":"talk.ch18_5_4106#originalText","id":"talk.ch18_5_4106","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"虽说没有别的手段了──","en":"Even if there was no other way...","ja":"ほかに手段がなかったとはいえ――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4107#originalText","id":"talk.ch18_5_4107","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"但接受了他们的连接，就等于是爱丽丝计划的情报有一半公诸于世了。","en":"...letting those players in has made some information on Project Alicization public.","ja":"彼らを受け入れてしまったことで、アリシゼーション計画の情報は、半ば公になってしまったのね"},"kind":"dialogue"},{"uid":"talk.ch18_5_4108#originalText","id":"talk.ch18_5_4108","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"比起让爱丽丝落入敌人手中变成受支配的AI，被使用在无人兵器上面，现状好太多了。","en":"Better this than Alice falling into enemy hands and being used as an AI on an unmanned weapon.","ja":"アリスが敵の手に渡って、ただ支配されるだけのAIとして無人兵器に使われるよりずっといいッスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4109#originalText","id":"talk.ch18_5_4109","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"说得也是……","en":"That's right...","ja":"そうッスよ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4110#originalText","id":"talk.ch18_5_4110","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"爱丽丝已经不是单纯用来控制UAV的AI了。","en":"Alice isn't just a control AI for UAVs anymore.","ja":"アリスはもう、ただのUAVコントロール用のAIなんかじゃない"},"kind":"dialogue"},{"uid":"talk.ch18_5_4111#originalText","id":"talk.ch18_5_4111","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"她是诞生在异世界中的新人类……","en":"She's a new form of humanity, born in a true alternate world.","ja":"本物の異世界に生まれた新しい人類なんだ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4112#originalText","id":"talk.ch18_5_4112","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"你早就明白这一点了，对吧？桐人小弟。","en":"You realized that long ago. Isn't that right, Kirito?","ja":"君にはとっくにそれがわかっていたそうッスよね、キリトくん"},"kind":"dialogue"},{"uid":"talk.ch18_5_4113#originalText","id":"talk.ch18_5_4113","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"嗯……？","en":"Hm?","ja":"ん……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4114#originalText","id":"talk.ch18_5_4114","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"咦、咦咦……？","en":"Huh...?","ja":"え、ええ……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4115#originalText","id":"talk.ch18_5_4115","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"等……等一下，凛子学姊，可以帮我看一下这个吗？","en":"H-Hey, Rin! Could you take a look at this?","ja":"ちょ……ちょっと凛子センパイこれ見てくれますか?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4116#originalText","id":"talk.ch18_5_4116","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"别用那种称呼方式叫我。","en":"Could you not call me that?","ja":"その呼び方やめてちょうだい"},"kind":"dialogue"},{"uid":"talk.ch18_5_4117#originalText","id":"talk.ch18_5_4117","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"这是显示桐谷小弟摇光的屏幕吧？这个变动是怎么回事……？","en":"This is Kirigaya's fluctlight monitor, isn't it? What are those fluctuations?","ja":"これは、桐ヶ谷君のフラクトライトモニタでしょ……この変動は何なの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4118#originalText","id":"talk.ch18_5_4118","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"这表示他丧失的意识一瞬间恢复了活性……","en":"It means his lost consciousness showed activity for just a moment.","ja":"彼の、喪失したはずの意識が一瞬だけ活性を示した……ってことなんスけど"},"kind":"dialogue"},{"uid":"talk.ch18_5_4119#originalText","id":"talk.ch18_5_4119","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"但这应该是不可能的啊。","en":"But there's no way that could happen.","ja":"そんなことあるはずないんですよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4120#originalText","id":"talk.ch18_5_4120","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"等一下，这个时间──","en":"Wait a moment. Those time stamps...","ja":"ちょっと待ってこの時間――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4121#originalText","id":"talk.ch18_5_4121","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"这两个时间点都是那些女孩用STL潜行的时刻吧？","en":"Aren't both of these times when the girls used the STL to dive?","ja":"これってどっちもあの子たちがSTLでダイブした頃じゃないの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4122#originalText","id":"talk.ch18_5_4122","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"咦，真的吗……呜哇，真的耶。","en":"Wow, really...? Wow, really!","ja":"え、マジっスか……うわ、マジっスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4123#originalText","id":"talk.ch18_5_4123","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"这是怎么回事……？","en":"What does this mean?","ja":"どういうことなんだ……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4124#originalText","id":"talk.ch18_5_4124","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"只是因为有熟悉的人出现……所以产生强烈反应吗？","en":"Is it just that he had a strong reaction because someone close to him showed up?","ja":"ただ、親しい人間が現れたから強い反応を示した……ってだけなのか?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4125#originalText","id":"talk.ch18_5_4125","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"不对，桐人小弟受到的伤害，不是这种情绪上的理由就能让他产生回复迹象。","en":"No, the damage Kirito sustained isn't something that could be repaired for such a poetic reason.","ja":"いや、キリト君のダメージは、そんなリリカルな理由で回復する代物じゃないはずだ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4126#originalText","id":"talk.ch18_5_4126","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"一定有别的理由……某种物质、逻辑上的理由……","en":"Something has to be causing this... Something physical and logical.","ja":"なにか、理由が……フィジカルでロジカルな理由があるはずなんだ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4127#originalText","id":"talk.ch18_5_4127","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"自我……主体……自己规定的自我形象……","en":"The self. The subject... The image that defines you as you.","ja":"自己……主体……自分を自分だと規定するイメージ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4128#originalText","id":"talk.ch18_5_4128","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"这些量子模式的备份还存在于某处吗？","en":"Could there be a backup of that quantum pattern somewhere?","ja":"その量子パターンのバックアップがどこかにあった……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4129#originalText","id":"talk.ch18_5_4129","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"不对，不可能啊！我们从没拷贝过桐人小弟的摇光。","en":"No, that's impossible. We never once duplicated Kirito's fluctlight.","ja":"いや、有り得ないキリト君のフラクトライトは一度もコピーしていない"},"kind":"dialogue"},{"uid":"talk.ch18_5_4130#originalText","id":"talk.ch18_5_4130","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"喂……","en":"Hey...","ja":"ねえ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4131#originalText","id":"talk.ch18_5_4131","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"就算有拷贝好了，也无法从中分离出自我形象并写入。","en":"Even if there was a backup, it would be impossible to extract the self-image and copy it over.","ja":"仮にコピーしていたところで、そこから自己イメージを切り出して書き込むなんて真似は不可能だ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4132#originalText","id":"talk.ch18_5_4132","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"听我说，比嘉……","en":"Hey, Higa.","ja":"ねえ、比嘉くん……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4133#originalText","id":"talk.ch18_5_4133","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"能和他的摇光连接的……有效的量子模式……","en":"Is there an active quantum pattern that can be connected to his fluctlight?","ja":"彼のフラクトライトと接続し得るような生きた量子パターンが……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4134#originalText","id":"talk.ch18_5_4134","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"在哪里……到底在哪里……？","en":"Where...? Where is it?","ja":"どこだ……どこに……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4135#originalText","id":"talk.ch18_5_4135","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"比嘉！","en":"Higa, listen!","ja":"比嘉くんってば!"},"kind":"dialogue"},{"uid":"talk.ch18_5_4136#originalText","id":"talk.ch18_5_4136","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"什么事？","en":"What is it?","ja":"なんッスか"},"kind":"dialogue"},{"uid":"talk.ch18_5_4137#originalText","id":"talk.ch18_5_4137","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"你之前就一直说的，主体的丧失，具体上是什么情形？","en":"You keep talking about the \"loss of the subject.\" What exactly does that mean?","ja":"前から君が言ってる、主体の喪失って具体的にどういうことなの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4138#originalText","id":"talk.ch18_5_4138","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"嗯……也就是呢……","en":"Well, put in other terms...","ja":"ええと……そりゃつまり……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4139#originalText","id":"talk.ch18_5_4139","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"《观察者、知觉者》……也就是心中的自己哟。","en":"\"That which sees, and thus knows\" —It's you, inside your head.","ja":"《見るものであり知るもの》……心の中の自分っスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4140#originalText","id":"talk.ch18_5_4140","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"以哲学来说，就是主体──客体问题。","en":"In philosophical terms, the subjective, rather than the objective.","ja":"哲学で言う、客体に対する主体"},"kind":"dialogue"},{"uid":"talk.ch18_5_4141#originalText","id":"talk.ch18_5_4141","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"透过感觉所接受的，处理所有情报的主要处理程序。","en":"The human being's main processor, which receives and sorts information from the senses.","ja":"感覚を通して受け取る、あらゆる情報を処理するメイン・プロセッサ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4142#originalText","id":"talk.ch18_5_4142","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"哦……也就是说，你使用STL来统合唯物论与二元论喽。","en":"Hmm... So through the STL, you've combined materialism with dualism.","ja":"ふうん……つまり君は、STLを使って唯物論と二元論を統合しちゃったわけね"},"kind":"dialogue"},{"uid":"talk.ch18_5_4143#originalText","id":"talk.ch18_5_4143","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"嗯，这不重要。","en":"That's fine.","ja":"まあそれはいいわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4144#originalText","id":"talk.ch18_5_4144","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"我想说的是，所谓的主体和客体，这两者有那么容易分割开来吗？","en":"But what I'm trying to get at is, can you really separate the subject and object that easily?","ja":"私が言いたいのは、主体と客体って、そんな簡単に切り分けられるものなのかってことよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4145#originalText","id":"talk.ch18_5_4145","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"……咦？","en":"Huh...?","ja":"……は?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4146#originalText","id":"talk.ch18_5_4146","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"无论是主体还是客体，都只是表现事物间关系的哲学概念吧。","en":"Aren't the subject and the object just philosophical concepts for expressing relationships?","ja":"主体とか客体は、あくまで物事の関係を表す哲学的な概念でしょ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4147#originalText","id":"talk.ch18_5_4147","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"人类可是社会性动物，不是以单一个人的形式存在于世上。","en":"Humans are social creatures. It's not as if we exist as solitary beings.","ja":"人間は社会的動物よ唯一の個人として存在しているわけじゃないわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4148#originalText","id":"talk.ch18_5_4148","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"自己心中的别人，别人心中的自己……","en":"The others who exist in you. The you that exists in others.","ja":"自分の中の他人、他人の中の自分……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4149#originalText","id":"talk.ch18_5_4149","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"这些在某种程度上，都像是经由网络链接在一起。","en":"Up to a point, they're all connected, like a network.","ja":"それらはある程度、ネットワーク的に接続しているところがある"},"kind":"dialogue"},{"uid":"talk.ch18_5_4150#originalText","id":"talk.ch18_5_4150","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"你不这么认为吗？","en":"Wouldn't you agree?","ja":"そうは思わない?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4151#originalText","id":"talk.ch18_5_4151","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"别人心中的……自己……","en":"The you...who exists...in others.","ja":"他人の……なかの……自分"},"kind":"dialogue"},{"uid":"talk.ch18_5_4152#originalText","id":"talk.ch18_5_4152","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"自我形象的备份……对哦……有啊，的确有啊！","en":"A backup self-image... That's right! We have it. We have it!","ja":"セルフイメージの、バックアップそうか……ある、あるッスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4153#originalText","id":"talk.ch18_5_4153","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"有数据可以补完桐人小弟被毁掉的主体！","en":"We have data we can use to restore Kirito's shattered subject!","ja":"キリト君の、吹っ飛ばされちまった主体を補完できるデータが!"},"kind":"dialogue"},{"uid":"talk.ch18_5_4154#originalText","id":"talk.ch18_5_4154","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"就在他熟悉的人们的摇光中！！","en":"It's inside the fluctlights of the people closest to him!","ja":"彼に近しい人たちの、フラクトライトの中に!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_4155#originalText","id":"talk.ch18_5_4155","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"可是，要抽出这些数据需要有STL……而且一个人的话重现度太单薄。","en":"But to extract that data, we need an STL... And we can't reproduce it well with just one person.","ja":"でも、それを抽出するにはSTLが必要だ……しかもひとりだけじゃ再現性が薄い"},"kind":"dialogue"},{"uid":"talk.ch18_5_4156#originalText","id":"talk.ch18_5_4156","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"至少要有两个……不，三个人……","en":"We'd need at least two... no, three people.","ja":"せめてふたり……いや、3人……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4157#originalText","id":"talk.ch18_5_4157","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"菊先生，从六本木潜行的那些女孩，都是跟桐人小弟有关的人吧……？","en":"Mr. Kiku, the girls diving from Roppongi are connected to Kirito, right?","ja":"菊サン。六本木からダイブしている子たちはキリト君の関係者……なんスよね?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4158#originalText","id":"talk.ch18_5_4158","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"嗯……没错。","en":"Yeah, that's right.","ja":"ああ……そうだ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4159#originalText","id":"talk.ch18_5_4159","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"诗乃是在半年前的《死枪事件》里，和桐人一起解决事件的伙伴。","en":"Sinon teamed up with Kirito to resolve the Death Gun incident six months ago.","ja":"シノン君は、半年前の《デスガン事件》をキリト君と一緒に解決した仲だ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4160#originalText","id":"talk.ch18_5_4160","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"而莉法则是桐人的妹妹。","en":"And Leafa is Kirito's younger sister.","ja":"そしてリーファ君は、キリト君の妹だよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4161#originalText","id":"talk.ch18_5_4161","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"有办法……或许能复原也说不定。能修复桐人小弟的自我形象！","en":"We can do it... We might be able to restore it, then. Kirito's self-image, that is!","ja":"できる……復元できるかも知れないッスキリト君のセルフイメージを!"},"kind":"dialogue"},{"uid":"talk.ch18_5_4162#originalText","id":"talk.ch18_5_4162","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"只要将保存在她们摇光中的，对桐人小弟的印象抽出来──","en":"If we can extract the image of Kirito saved onto their fluctlights...","ja":"彼女たちのフラクトライトに保存されているはずのキリト君のイメージを抽出して――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4163#originalText","id":"talk.ch18_5_4163","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"然后和丧失领域联结起来的话……这个有效文件应该就能回复桐人小弟本来的主体了……","en":"...and connect it to the areas he's lost, that living data should help restore his subjective sense!","ja":"喪失領域に繋いでやれば……その生きたデータはキリト君の本来の主体を回復させ得るはずだ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4164#originalText","id":"talk.ch18_5_4164","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"有了……终于有方法了！","en":"That's it... That should do it!","ja":"……来た来たっスよこれ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_4165#originalText","id":"talk.ch18_5_4165","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"啊……啊啊……不会吧……啊啊啊……","en":"Oh! Argh... You're kidding me...","ja":"あっ……ああ……嘘だろ……あああ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4166#originalText","id":"talk.ch18_5_4166","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"能进行这种操作的……只有主控室而已。","en":"The only place we can do that is the Main Control Room.","ja":"その操作ができるのはメインコントロールルームだけッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4167#originalText","id":"talk.ch18_5_4167","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"啊啊……","en":"Oh...","ja":"ああ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4168#originalText","id":"talk.ch18_5_4168","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"别那么沮丧，比嘉。光是知道桐人的治疗又有希望就够了。","en":"Don't be so disappointed, Higa. It's good knowing that there's hope for Kirito.","ja":"そうしょげるな、比嘉君。キリト君の治療に光明が見えただけでも良しとしよう"},"kind":"dialogue"},{"uid":"talk.ch18_5_4169#originalText","id":"talk.ch18_5_4169","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"实际的操作就等状况结束，将那些家伙赶出Ocean Turtle再说。","en":"We can launch the operation after all this is resolved and those people are off the Ocean Turtle.","ja":"実際のオペレーションは、状況が終了しオーシャン・タートルから連中を追い出した後にしよう"},"kind":"dialogue"},{"uid":"talk.ch18_5_4170#originalText","id":"talk.ch18_5_4170","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"可是那样就太晚了……","en":"But by then...it'll be too late.","ja":"それじゃあ……遅いんスよ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4171#originalText","id":"talk.ch18_5_4171","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"要是突击队从护卫舰《朝日》攻进来，发生大规模战斗的话，副电源也会断掉吧？","en":"If the commando unit from Asahi storms in, the sub-power would probably get knocked out, too.","ja":"護衛艦《あさひ》からコマンド部隊が突入してきて大規模な戦闘になったら、サブ電源も落ちるでしょう"},"kind":"dialogue"},{"uid":"talk.ch18_5_4172#originalText","id":"talk.ch18_5_4172","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"要是那样的话，桐人小弟就会在没有意识的状态下强制从Underworld注销。","en":"If that were to happen, Kirito would be forcibly logged out of Underworld while still unconscious.","ja":"そんなことになったら、キリト君はアンダーワールドから意識不明のまま強制的にログアウトしてしまう"},"kind":"dialogue"},{"uid":"talk.ch18_5_4173#originalText","id":"talk.ch18_5_4173","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"那么一来，桐人小弟八成无法通过登录所需的初期阶段认证──","en":"And then most likely, Kirito wouldn't make it past the initialization stage to log in...","ja":"そしたら、おそらくキリト君はログインに必要な初期ステージを通過できず――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4174#originalText","id":"talk.ch18_5_4174","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"会变得再也无法和STL连接。","en":"...and he'll never be able to connect to the STL again.","ja":"二度とSTLに接続できません"},"kind":"dialogue"},{"uid":"talk.ch18_5_4175#originalText","id":"talk.ch18_5_4175","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"所以，无论如何都得趁他跟那三个女孩同时潜行到Underworld的期间──","en":"That's why, no matter what, we have to treat him while he and those three girls","ja":"だから、何としても彼と3人の女の子たちがアンダーワールドにダイブしている間に――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4176#originalText","id":"talk.ch18_5_4176","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"把握时间进行治疗才行。","en":"are still diving in Underworld.","ja":"治療を行わなくちゃならないッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4177#originalText","id":"talk.ch18_5_4177","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch18_5_4178#originalText","id":"talk.ch18_5_4178","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"菊先生，我决定要过去了。","en":"I'm going, okay, Mr. Kiku?","ja":"……僕、行くッスよ、菊サン"},"kind":"dialogue"},{"uid":"talk.ch18_5_4179#originalText","id":"talk.ch18_5_4179","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"你说过去……是要去哪里？","en":"Going...where?","ja":"行くとは……どこにだ?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4180#originalText","id":"talk.ch18_5_4180","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"桐人小弟所在的第二STL室和耐压隔板下方的主控室──","en":"STL Room Two, where Kirito is now, and Maincon below the pressure bulkhead...","ja":"キリト君がいる第二STL室と、耐圧隔壁の下のメインコンとは――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4181#originalText","id":"talk.ch18_5_4181","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"是由主轴船尾侧的光纤导管连接起来的。","en":"...are connected by a cable duct on the stern side of the Main Shaft.","ja":"メインシャフト船尾側のケーブルダクトで繋がっています"},"kind":"dialogue"},{"uid":"talk.ch18_5_4182#originalText","id":"talk.ch18_5_4182","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"那上面应该有一处检修用的电子连接器。","en":"There should be a maintenance connector in there.","ja":"あそこには、一カ所だけ点検用のコネクタがあったはずッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4183#originalText","id":"talk.ch18_5_4183","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"只要从那里就能操纵桐人小弟的STL了。","en":"I should be able to control Kirito's STL from there.","ja":"そこからなら、キリト君のSTLを操作することが可能です"},"kind":"dialogue"},{"uid":"talk.ch18_5_4184#originalText","id":"talk.ch18_5_4184","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"可是，电子连接器在耐压隔板的另一边。","en":"But the maintenance connector is on the other side of the pressure bulkhead.","ja":"しかし、点検コネクタは耐圧隔壁の向こう側だぞ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4185#originalText","id":"talk.ch18_5_4185","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"要是被发现的话，可能会被敌人从下方攻击。","en":"If they notice you, you could get attacked from below.","ja":"もし気づかれたら、下から攻撃される可能性もある"},"kind":"dialogue"},{"uid":"talk.ch18_5_4186#originalText","id":"talk.ch18_5_4186","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"关于这点，就用诱饵作战解决吧！","en":"So let's go with a decoy operation!","ja":"そこは、囮作戦でいきましょう"},"kind":"dialogue"},{"uid":"talk.ch18_5_4187#originalText","id":"talk.ch18_5_4187","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"你说诱饵……？","en":"Decoy, did you say?","ja":"オトリ……だと?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4188#originalText","id":"talk.ch18_5_4188","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"我说的不是要投入珍贵的人才。","en":"We wouldn't send in valuable human resources. Once we unlock the pressure bulkhead door...","ja":"もちろん、貴重な人材を投入しようってわけじゃないッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4189#originalText","id":"talk.ch18_5_4189","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"解除隔板的锁之后，就让「那个」从导管另一端──","en":"...we'll have it charge down the stairs for humans on the other side of the duct.","ja":"隔壁のロックを解除したら、ダクトの反対側にある人間用の階段から、下に突入させるんス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4190#originalText","id":"talk.ch18_5_4190","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"人类用的阶梯冲下去。","en":"That.","ja":"……あれを"},"kind":"dialogue"},{"uid":"talk.ch18_5_4191#originalText","id":"talk.ch18_5_4191","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"原来如此……你是说《一卫门》吗？","en":"I see... You mean Ichiemon.","ja":"なるほど……《イチエモン》か"},"kind":"dialogue"},{"uid":"talk.ch18_5_4192#originalText","id":"talk.ch18_5_4192","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"等等，它只能缓缓的上下楼梯而已。","en":"Hold on! All that one can do now is slowly go up and down stairs.","ja":"ちょっと、あれはまだ、階段をゆっくり上り下りすることしかできないわよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4193#originalText","id":"talk.ch18_5_4193","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"没办法吸引敌人注意后马上跑回来。","en":"It can't possibly rush back here if the enemy spots it!","ja":"敵の注意を引いて、すぐに駆け戻ってくるなんて真似は不可能よ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4194#originalText","id":"talk.ch18_5_4194","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"虽然对一卫门不好意思，但只能请它好好加油了。","en":"I do feel bad for Ichiemon, but he's just going to have to do his best.","ja":"イチエモンには悪いですけど、頑張って貰うしかないッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4195#originalText","id":"talk.ch18_5_4195","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"它外表比较特殊，或许敌人也不敢一下就开枪射击。","en":"But given the way he looks, the enemy might not open fire on him.","ja":"ただ、見た目がアレなんで、敵もいきなり撃ったりはしないかもしれません"},"kind":"dialogue"},{"uid":"talk.ch18_5_4196#originalText","id":"talk.ch18_5_4196","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"的确，它的外表很抢眼。","en":"Well, that's true. He's sure to stick out like a sore thumb.","ja":"……まあ、確かにこの外見なら大いに目立つし"},"kind":"dialogue"},{"uid":"talk.ch18_5_4197#originalText","id":"talk.ch18_5_4197","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"或许能让对方以为我们有什么不得了的计划……","en":"So we can probably convince them that we have an epic plan up our sleeves.","ja":"こっちが何かとんでもないことを企んでいるように思わせられるでしょうけどね……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4198#originalText","id":"talk.ch18_5_4198","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"至少，他们应该无法无视它。","en":"At the very least, they won't be able to ignore him.","ja":"少なくとも、無視はできないはずッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4199#originalText","id":"talk.ch18_5_4199","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"在敌人顾着对付一卫门时，我就入侵光纤导管的下层──","en":"So, while the enemy is dealing with Ichiemon, I'll infiltrate the lower cable duct...","ja":"敵がイチエモンに対応している間に、僕がケーブルダクト下部に侵入――"},"kind":"dialogue"},{"uid":"talk.ch18_5_4200#originalText","id":"talk.ch18_5_4200","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"从电子连接器操纵桐人小弟的STL。","en":"...and access Kirito's STL through the maintenance connector.","ja":"点検コネクタからキリト君のSTLを操作します"},"kind":"dialogue"},{"uid":"talk.ch18_5_4201#originalText","id":"talk.ch18_5_4201","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"要不要干脆……连《二卫门》也一起投入？","en":"While we're at it, do you think we could deploy Niemon, too?","ja":"いっそのこと、《ニエモン》も投入できないか?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4202#originalText","id":"talk.ch18_5_4202","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"很可惜的，没有办法。","en":"Unfortunately, that's not possible.","ja":"残念ながら無理ッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4203#originalText","id":"talk.ch18_5_4203","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"没有搭载平衡器的二卫门，刚开始下楼就会跌倒了吧。","en":"Like I said before, without a balancer, Niemon will only fall over as soon as he's on the stairs.","ja":"バランサーを搭載していない今のニエモンじゃ階段を降り始めた途端に転ぶッスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4204#originalText","id":"talk.ch18_5_4204","speaker":{"cn":"菊冈","en":"Kikuoka","ja":"菊岡"},"text":{"cn":"这样啊……","en":"I see.","ja":"そうか……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4205#originalText","id":"talk.ch18_5_4205","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"可是，比嘉……","en":"But Higa, even if you did fool them long enough to unlock the bulkhead...","ja":"でも、比嘉君"},"kind":"dialogue"},{"uid":"talk.ch18_5_4206#originalText","id":"talk.ch18_5_4206","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"就算这样可以隐瞒隔板已经解锁的事，但你还是有被发现的危险性啊。","en":"...there'd still be some risk of you being spotted.","ja":"隔壁のロック解除はそれでごまかせたとしても君が発見される危険が完全に消滅するわけじゃないわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4207#originalText","id":"talk.ch18_5_4207","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"还是带着护卫一起去比较好吧？","en":"Shouldn't you take a bodyguard with you?","ja":"護衛してくれる人を連れていったほうがいいんじゃないの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_4208#originalText","id":"talk.ch18_5_4208","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"不，这种情况下，自卫官工作人员是非常重要的战力。","en":"No. As it stands now, we can't spare any of the JSDF staff.","ja":"いえ、今の状況で自衛官スタッフは貴重すぎる戦力ッス"},"kind":"dialogue"},{"uid":"talk.ch18_5_4209#originalText","id":"talk.ch18_5_4209","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"而且，能在那么狭窄的导管迅速移动的人，只有我这个瘦小的矮子而已。","en":"Besides, the only one who can easily move through that cramped duct...is scrawny little me.","ja":"それに、あんなクソ狭いダクトを素早く移動できるのは、ガリチビの僕くらいッスよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_4210#originalText","id":"talk.ch18_5_4210","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"我会快去快回的。","en":"I'm going to zip over, and zip right back, okay?","ja":"さっと行って、さっと帰って来ますから"},"kind":"dialogue"},{"uid":"talk.ch18_5_4211#originalText","id":"talk.ch18_5_4211","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"要是没有桐人小弟在，爱丽丝的摇光一定无法成长到现在这个程度。","en":"If it weren't for Kirito, Alice's fluctlight wouldn't have become what it is now.","ja":"……キリト君がいなければ、アリスのフラクトライトはきっと、今のようにはならなかった"},"kind":"dialogue"},{"uid":"talk.ch18_5_4212#originalText","id":"talk.ch18_5_4212","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"光是这样他就有很大的功劳了──结果他却为了保护爱丽丝而……","en":"That alone is such a great achievement, but while trying to protect Alice...","ja":"それだけでも彼の功績はすごいものなのに――アリスを守ろうとして……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4213#originalText","id":"talk.ch18_5_4213","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"所以，要是有机会能治好他，不管冒什么危险我都要试试看。","en":"That's why, if there's a chance we can treat him, we have to take any risk.","ja":"だから、彼を治療できる可能性があるならどんなリスクを負ってでも挑まないと"},"kind":"dialogue"},{"uid":"talk.ch18_5_4214#originalText","id":"talk.ch18_5_4214","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"不然就没脸见桐人小弟了。","en":"Or we won't be able to look him in the eye, right?","ja":"キリト君に顔向けできないッスよね"},"kind":"dialogue"},{"uid":"talk.ch18_5_4215#originalText","id":"talk.ch18_5_4215","speaker":{"cn":"柳井","en":"Yanai","ja":"柳井"},"text":{"cn":"那个……","en":"Um...","ja":"あのぉ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4216#originalText","id":"talk.ch18_5_4216","speaker":{"cn":"柳井","en":"Yanai","ja":"柳井"},"text":{"cn":"我也要跟比嘉主任一起去……","en":"I'll go with you, Chief Higa.","ja":"私も比嘉チーフと一緒に行きます……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4217#originalText","id":"talk.ch18_5_4217","speaker":{"cn":"柳井","en":"Yanai","ja":"柳井"},"text":{"cn":"我的身材也很瘦小，不过，至少能帮主任挡子弹吧……","en":"As you can see, I'm scrawny, too, but I think I can at least take a bullet for you.","ja":"私もこんなにガリガリですし、でもチーフの弾除けくらいにはなるかな、って……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4218#originalText","id":"talk.ch18_5_4218","speaker":{"cn":"柳井","en":"Yanai","ja":"柳井"},"text":{"cn":"而且至今负责保养光纤设备的人就是我啊……","en":"And besides, I'm the one who's been maintaining those cables till now.","ja":"それに、これまでケーブルまわりの保守してきたの、私ですから……"},"kind":"dialogue"},{"uid":"talk.ch18_5_4219#originalText","id":"talk.ch18_5_4219","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"说实在的，我也不太记得电子连接器在哪里了。","en":"To be honest, I don't really remember where the maintenance connector is.","ja":"ほんとのトコ、点検コネクタの位置をいまいち覚えてないんスよね"},"kind":"dialogue"},{"uid":"talk.ch18_5_4220#originalText","id":"talk.ch18_5_4220","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"就麻烦你跟我一起去吧，柳井先生。","en":"So thanks for coming along, Mr. Yanai.","ja":"ありがたく同行をお願いします柳井さん"},"kind":"dialogue"},{"uid":"talk.ch18_5_1101#originalText","id":"talk.ch18_5_1101","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"亚丝娜，我看到从这里往南5公里处有座像是遗迹的废墟。","en":"Asuna, about five kilometers south from here, you'll see what looks like abandoned ruins.","ja":"アスナ、ここから5キロくらい南に行ったところに遺跡みたいな廃墟が見えたわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_1102#originalText","id":"talk.ch18_5_1102","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"到那边的话，应该能在不被包围的情况下迎击敌人。","en":"I think we can attack the enemy there without being surrounded.","ja":"あそこでなら、包囲されずに敵を迎え撃てると思う"},"kind":"dialogue"},{"uid":"talk.ch18_5_1103#originalText","id":"talk.ch18_5_1103","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我知道了，诗乃。","en":"All right, Sinon.","ja":"わかったわ、シノン"},"kind":"dialogue"},{"uid":"talk.ch18_5_1104#originalText","id":"talk.ch18_5_1104","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算美国的VRMMO玩家再多，他们应该无法马上招揽更多玩家进来。","en":"No matter how huge the American VRMMO population may be, I doubt they can get any more right away.","ja":"いくらアメリカのVRMMO人口が多くてもこれ以上の数は、すぐには用意できないはず"},"kind":"dialogue"},{"uid":"talk.ch18_5_1105#originalText","id":"talk.ch18_5_1105","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"只要击退现有的玩家，敌人应该就无计可施了。","en":"If we can beat the players they have now, the enemy won't be able to do anything...I think.","ja":"今いるプレイヤーを撃退すれば、敵に打てる手はもうない……と思うわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_1106#originalText","id":"talk.ch18_5_1106","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"知道了。话说回来……","en":"All right. So, by the way...","ja":"わかったそれはそうと……"},"kind":"dialogue"},{"uid":"talk.ch18_5_1107#originalText","id":"talk.ch18_5_1107","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"桐人在这个部队吗……？","en":"Is Kirito in this unit?","ja":"……その、キリトは、この部隊にいるの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_1108#originalText","id":"talk.ch18_5_1108","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"事到如今不需要用那么见外的问法啦，桐人他在这辆马车里。","en":"There's no need for you to sound so formal. Kirito's in this wagon.","ja":"いまさらそんな、水臭い訊き方しなくてもいいわよキリトくんは、この馬車の中"},"kind":"dialogue"},{"uid":"talk.ch18_5_1109#originalText","id":"talk.ch18_5_1109","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这样啊。那……我去跟他打个招呼吧。","en":"Is that so? Then I guess I'll go say hi.","ja":"え、そうなのじゃあ……ちょっと、挨拶してくるわね"},"kind":"dialogue"},{"uid":"talk.ch18_5_1110#originalText","id":"talk.ch18_5_1110","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"索……索鲁斯大人……？","en":"L-Lady Solus?","ja":"そ、ソルス様……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_1111#originalText","id":"talk.ch18_5_1111","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"初次见面，妳们好。虽然我看起来像索鲁斯，但内在不是。","en":"Hello! Nice to meet you. I may look like Solus, but I'm not on the inside.","ja":"こんにちは、はじめましてソルスっぽいけど、中身は違うの"},"kind":"dialogue"},{"uid":"talk.ch18_5_1112#originalText","id":"talk.ch18_5_1112","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我的名字叫诗乃。","en":"My name is Sinon.","ja":"私の名前はシノン"},"kind":"dialogue"},{"uid":"talk.ch18_5_1113#originalText","id":"talk.ch18_5_1113","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"没错，我跟亚丝娜一样是现实世界人，同时也是桐人的……朋友。","en":"That's right. Like Asuna, I'm from the real world. And I'm Kirito's...friend.","ja":"そう、私もアスナと同じ、リアルワールド人よそして、キリトの……友だち"},"kind":"dialogue"},{"uid":"talk.ch18_5_1114#originalText","id":"talk.ch18_5_1114","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这样啊……","en":"I see...","ja":"そう……なんですか"},"kind":"dialogue"},{"uid":"talk.ch18_5_1115#originalText","id":"talk.ch18_5_1115","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"全都是女生……","en":"They're all female.","ja":"女の人ばっかり"},"kind":"dialogue"},{"uid":"talk.ch18_5_1116#originalText","id":"talk.ch18_5_1116","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"可不只有这些呢！","en":"And we're not the only ones.","ja":"まだまだこんなもんじゃないわよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_1117#originalText","id":"talk.ch18_5_1117","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch18_5_1118#originalText","id":"talk.ch18_5_1118","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"就算桐人的心深深受到伤害……还是有很多人能明白你的心情。","en":"Even if your soul's been deeply damaged, there are so many people who know your soul so well.","ja":"……キリトの心が、深く傷ついてしまっても沢山の人があなたの心を知っているわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_1119#originalText","id":"talk.ch18_5_1119","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你看，能感受到吧……在我心中的你……","en":"See, can't you feel it? The you that's inside me.","ja":"ほら、感じるでしょ……私のなかの君を"},"kind":"dialogue"},{"uid":"talk.ch18_5_1120#originalText","id":"talk.ch18_5_1120","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"喜欢讽刺、恶作剧、顽固又天真，比任何人都强都温柔的你。","en":"The sarcastic, mischievous, stubborn, and naive one... The strongest, kindest of all.","ja":"皮肉屋で、悪戯好きで、頑固で、ナイーブで……そして誰よりも強くて優しい、君自身を"},"kind":"dialogue"},{"uid":"talk.ch18_5_1121#originalText","id":"talk.ch18_5_1121","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不用担心，当大家真的需要桐人的时候，他很快就会好起来了。","en":"Don't worry. Kirito will be better in no time. At the moment when we really need him, right?","ja":"……大丈夫、キリトはすぐに元気になるわよみんなが、本当にこの人を必要とした時に、ね"},"kind":"dialogue"},{"uid":"talk.ch18_5_1122#originalText","id":"talk.ch18_5_1122","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……嗯。","en":"Yeah...","ja":"……うん"},"kind":"dialogue"},{"uid":"talk.ch18_5_1123#originalText","id":"talk.ch18_5_1123","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"那……我先飞到南方的遗迹确认一下地形。","en":"All right. I'm going to go on ahead and fly to the ruins to get the lay of the land.","ja":"じゃあ……私、一足さきに南の遺跡まで飛んで地形を確認してくる"},"kind":"dialogue"},{"uid":"talk.ch18_5_1124#originalText","id":"talk.ch18_5_1124","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"桐人就拜托妳们照顾了。","en":"You guys look after Kirito, okay?","ja":"あなたたち、キリトのこと、よろしくね"},"kind":"dialogue"},{"uid":"talk.ch18_5_1125#originalText","id":"talk.ch18_5_1125","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"等一下，诗乃，妳刚才说「飞」吗？妳能飞吗？","en":"H-Hey, Sinon, did you just say \"fly\"? Meaning... You can fly?","ja":"ね、ねえシノン、いま「飛ぶ」って言った?あなた、飛べるの?"},"kind":"dialogue"},{"uid":"talk.ch18_5_1126#originalText","id":"talk.ch18_5_1126","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"对啊，这好像是索鲁斯帐号的专属能力，听说也没有时间限制。","en":"Y-Yeah. Apparently, it's a unique power gifted to the Solus account. There's no time limit either.","ja":"う……うん、ソルス・アカウントの固有能力らしいわ制限時間とかもないって聞いたけど"},"kind":"dialogue"},{"uid":"talk.ch18_5_1127#originalText","id":"talk.ch18_5_1127","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"既然这样，最需要妳帮忙的不是我们！去追爱丽丝……去追被皇帝抓走的爱丽丝小姐吧！","en":"Then we're not the ones who need to be rescued! It's Alice. She's been abducted by the emperor!","ja":"なら、助けてほしいのはわたしたちじゃないわ!アリスを……皇帝に攫われたアリスさんを追いかけて!"},"kind":"dialogue"},{"uid":"talk.ch18_5_1201#originalText","id":"talk.ch18_5_1201","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch18_5_1202#originalText","id":"talk.ch18_5_1202","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"……啊……","en":"Oh...","ja":"……あ……"},"kind":"dialogue"},{"uid":"talk.ch18_5_1204#originalText","id":"talk.ch18_5_1204","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"莲……","en":"Len...","ja":"……レン"},"kind":"dialogue"},{"uid":"talk.ch18_5_1205#originalText","id":"talk.ch18_5_1205","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"我们到底是为了什么而战……","en":"What were we eben fighting for?","ja":"おでたちは、いったいなんのために戦っていたのだ"},"kind":"dialogue"},{"uid":"talk.ch18_5_1206#originalText","id":"talk.ch18_5_1206","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"为什么莲他们非得为了那些家伙丧命……","en":"Why did you all hab to die for dem?","ja":"なぜ、あいつらのためにレンたちが死なねば……"},"kind":"dialogue"},{"uid":"talk.ch18_5_1207#originalText","id":"talk.ch18_5_1207","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呀啊啊啊啊啊！！！","en":"Ahhh!!!","ja":"きゃあああああっ!!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_1208#originalText","id":"talk.ch18_5_1208","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"什……！？","en":"What?!","ja":"な……!?"},"kind":"dialogue"},{"uid":"talk.ch18_5_1209#originalText","id":"talk.ch18_5_1209","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"所以我才讨厌全新的机器啊！","en":"Jeez... That's why I hate new devices!","ja":"だから新品の機械ってイヤなのよ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2101#originalText","id":"talk.ch18_5_2101","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在拜托诗乃去追爱丽丝小姐之后，我们朝着南方的遗迹前进。","en":"After I asked Sinon to find Alice, we headed towards the ruins to the south.","ja":"シノンにアリスさんを追いかけてもらった後わたしたちは南の遺跡へ向かった"},"kind":"dialogue"},{"uid":"talk.ch18_5_2102#originalText","id":"talk.ch18_5_2102","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"与敌人拉开一些距离，前进了20分钟左右后，出现了类似巨大神殿的建筑物。","en":"20 minutes later, having drawn away from the enemy, we came upon a giant temple of sorts.","ja":"敵を少しだけ引き離し、20分ほど進むと巨大な神殿のような建物が現れた"},"kind":"dialogue"},{"uid":"talk.ch18_5_2103#originalText","id":"talk.ch18_5_2103","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"宽度有300公尺以上，足以当成防止敌军包围的屏障了。","en":"It was over 300 meters wide - more than big enough to block an enemy siege.","ja":"幅は300メートル以上あり、敵の包囲を防ぐ障壁としては充分だ"},"kind":"dialogue"},{"uid":"talk.ch18_5_2104#originalText","id":"talk.ch18_5_2104","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在那条参拜道路的中段迎击敌人吧！","en":"Let's fight back against the enemy in the middle of that ceremonial path!","ja":"あの参道の中ほどで、敵を迎え撃ちましょう!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2105#originalText","id":"talk.ch18_5_2105","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"明白了！","en":"Understood!","ja":"了解です!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2106#originalText","id":"talk.ch18_5_2106","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"好了，前卫部队分为左右两边停下来！让马车队与后卫部队通过！","en":"Lead group, split to both sides and stand your ground! Let the wagons and the rear group through!","ja":"よし、前衛部隊は左右に分かれて停止!馬車隊と後衛部隊を通せ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2107#originalText","id":"talk.ch18_5_2107","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……敌人好像来了。","en":"It seems they've arrived.","ja":"……来たようですね"},"kind":"dialogue"},{"uid":"talk.ch18_5_2108#originalText","id":"talk.ch18_5_2108","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"刚才的声音是……！","en":"What was that noise?","ja":"今の音は……!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2109#originalText","id":"talk.ch18_5_2109","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……！","en":"...!","ja":"……っ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2110#originalText","id":"talk.ch18_5_2110","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这就是最后一战了，桐人就拜托妳们照顾了。","en":"This is the final battle. I'm counting on you to take care of Kirito.","ja":"これが最後の戦いよキリトくんのこと、お願いするわね"},"kind":"dialogue"},{"uid":"talk.ch18_5_2111#originalText","id":"talk.ch18_5_2111","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"好的！交给我们吧，亚丝娜大人！","en":"Right! Please leave it to us, Lady Asuna!","ja":"はい!お任せください、アスナ様!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2112#originalText","id":"talk.ch18_5_2112","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我们一定会保护他的！","en":"We promise to protect him.","ja":"必ずお守りいたします!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2113#originalText","id":"talk.ch18_5_2113","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"赌上性命也在所不惜──","en":"Even if it costs us our lives.","ja":"――命に代えても"},"kind":"dialogue"},{"uid":"talk.ch18_5_2114#originalText","id":"talk.ch18_5_2114","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不用担心，我绝对不会让敌人攻进来的。","en":"Don't worry. We won't let the enemy get this far.","ja":"大丈夫、絶対にここまで敵は通さないから"},"kind":"dialogue"},{"uid":"talk.ch18_5_2301#originalText","id":"talk.ch18_5_2301","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch18_5_2302#originalText","id":"talk.ch18_5_2302","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"呵呵，那女人还是老样子，一抓狂下手就毫不留情，杀个不停呢。","en":"Hehehe. As merciless as ever when she snaps. I'm so going to kill that woman.","ja":"くくっ、相変わらずキレると容赦ないな、あの女殺す殺す"},"kind":"dialogue"},{"uid":"talk.ch18_5_2303#originalText","id":"talk.ch18_5_2303","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咕……呜……呜呜！！","en":"Mmf...ah...urgh!","ja":"く……う……うぅッ!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2304#originalText","id":"talk.ch18_5_2304","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"──才不痛呢！这点伤势，一点都不痛！","en":"This doesn't hurt... I swear, this doesn't hurt!","ja":"――痛いもんか痛いもんか、こんな傷!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2305#originalText","id":"talk.ch18_5_2305","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"只有心灵撑不下去时，这具身躯才会倒下。既然这样，我就可以永远站下去。","en":"My body won't give out until my mind does. So I will stay standing forever!","ja":"この体が倒れるのは、心が折れた時だけならわたしは、永遠に立ち続けられる!"},"kind":"dialogue"},{"uid":"talk.ch18_5_2306#originalText","id":"talk.ch18_5_2306","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"是敌人的……援军？","en":"Enemy...reinforcements?","ja":"敵の……援軍?"},"kind":"dialogue"},{"uid":"talk.ch18_5_2307#originalText","id":"talk.ch18_5_2307","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"剑技？","en":"A sword...skill?","ja":"ソード、スキル?"},"kind":"dialogue"},{"uid":"talk.ch18_5_2308#originalText","id":"talk.ch18_5_2308","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"哟，让妳久等了，亚丝娜。","en":"Hey, sorry to keep you waiting, Asuna.","ja":"おう、待たせたな、アスナ"},"kind":"dialogue"},{"uid":"talk.ch18_5_2309#originalText","id":"talk.ch18_5_2309","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"克莱因……先生。","en":"Klein...?","ja":"クライン……さん"},"kind":"dialogue"},{"uid":"talk.ch18_5_3101#originalText","id":"talk.ch18_5_3101","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"喔啦！","en":"Yah!","ja":"オラアッ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3102#originalText","id":"talk.ch18_5_3102","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"艾基尔先生！","en":"Agil!","ja":"エギルさん!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3103#originalText","id":"talk.ch18_5_3103","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我来晚了。","en":"Sorry I didn't get here sooner.","ja":"遅くなっちまったな"},"kind":"dialogue"},{"uid":"talk.ch18_5_3104#originalText","id":"talk.ch18_5_3104","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹！！西莉卡！！","en":"Liz! Silica!","ja":"リズ!!シリカちゃん!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3105#originalText","id":"talk.ch18_5_3105","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你们……来帮我了吗……","en":"You came... You actually came!","ja":"来て……来てくれたのね……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3106#originalText","id":"talk.ch18_5_3106","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"当然要来呀。","en":"Of course we'd come.","ja":"来るわよ、もちろん"},"kind":"dialogue"},{"uid":"talk.ch18_5_3107#originalText","id":"talk.ch18_5_3107","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"这还用说吗！","en":"How could we not?","ja":"当ったり前じゃないですか!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3108#originalText","id":"talk.ch18_5_3108","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"怎么这么乱来……全身都是伤……妳太拼了啦，亚丝娜。","en":"You've been pushing yourself so hard... Look how banged up you are, Asuna.","ja":"こんなに無茶して……傷だらけになって……がんばりすぎだよ、アスナ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3109#originalText","id":"talk.ch18_5_3109","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"剩下的交给我们吧。大家都来了哦！","en":"Leave the rest to us. Everyone's here!","ja":"あとは任せてくださいみんな、来てくれましたから"},"kind":"dialogue"},{"uid":"talk.ch18_5_3110#originalText","id":"talk.ch18_5_3110","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大家……？","en":"Everyone?","ja":"みんな……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_3111#originalText","id":"talk.ch18_5_3111","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"那些红色的家伙就是敌人～！","en":"Those red guys are the enemy!","ja":"あの赤いのが敵ダー!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3112#originalText","id":"talk.ch18_5_3112","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"前卫，突击！将战线推回去！","en":"Vanguard, charge! Push them back!","ja":"前衛、突撃!押し返せ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3113#originalText","id":"talk.ch18_5_3113","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"后卫先跟Underworld人的部队确认咒文！","en":"Rearguard, join the Underworld forces for now, and check your spells!","ja":"後衛はいったん、アンダーワールド人部隊と呪文を確認!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3114#originalText","id":"talk.ch18_5_3114","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"虽然我跟你们无冤无仇……","en":"It's not like we have a personal beef with you.","ja":"てめぇらに個人的な恨みはねぇが……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3115#originalText","id":"talk.ch18_5_3115","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"但好友被你们痛扁的帐，一定要跟你们算！","en":"But we're going to make you pay for what you did to our friend.","ja":"ダチをさんざ痛めつけてくれた借りは返すぜ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3116#originalText","id":"talk.ch18_5_3116","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"要三倍奉还……不对，是千倍奉还才对，你们这群混帐！！","en":"Three times the amount... No, make it a thousand, you bastards!","ja":"三倍返し……いや、千倍返しだこの野郎ども!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3117#originalText","id":"talk.ch18_5_3117","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"各位……明明不确定能不能转移回去……对不起，对不起……","en":"You might not even make it back. Sorry... I'm so sorry...","ja":"みんな……帰れるかもわからないのにごめん……ごめんね"},"kind":"dialogue"},{"uid":"talk.ch18_5_3118#originalText","id":"talk.ch18_5_3118","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"妳在说什么啊，亚丝娜。","en":"What are you talking about, Asuna?","ja":"何言ってるのよ、アスナ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3119#originalText","id":"talk.ch18_5_3119","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我们之所以在SAO和ALO一路努力到现在──","en":"I believe we all made it through SAO and ALO...","ja":"あたしたちがSAOやALOで頑張ってきたのは――"},"kind":"dialogue"},{"uid":"talk.ch18_5_3120#originalText","id":"talk.ch18_5_3120","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"一定就是为了这一刻，要在这里守护重要的事物。","en":"...so that we could protect what we love right here, right now.","ja":"きっといまこの場所で大切なものを守るためだったんだよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3121#originalText","id":"talk.ch18_5_3121","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯……说得也是，谢谢你们……","en":"Yeah. You're right. Thank you.","ja":"うん……そうだね、ありがとう……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3122#originalText","id":"talk.ch18_5_3122","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹、西莉卡，是谁将你们大家带来这里的……？","en":"Hey, Liz, Silica, who was it that brought you all here?","ja":"ねえリズ、シリカちゃんみんなをここに連れてきてくれたのは、誰なの……?"},"kind":"dialogue"},{"uid":"talk.ch18_5_3123#originalText","id":"talk.ch18_5_3123","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"拜托，亚丝娜，这还用说吗！","en":"Come on, Asuna, who do you think?","ja":"ちょっとアスナ、そんなの決まってるじゃないの!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3124#originalText","id":"talk.ch18_5_3124","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"当然是结衣呀！","en":"It was Yui.","ja":"ユイちゃんですよ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3125#originalText","id":"talk.ch18_5_3125","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"结衣拼命跟我们解释有关Underworld和这里的居民的事。","en":"Yui gave us this heartfelt speech about the Underworld and the people who live here.","ja":"ユイちゃんがアンダーワールドのことと、ここで生きてる人のことを、一生懸命説明してくれたんです"},"kind":"dialogue"},{"uid":"talk.ch18_5_3126#originalText","id":"talk.ch18_5_3126","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"谢谢妳，结衣……","en":"Thank you, Yui.","ja":"……ありがとう、ユイちゃん"},"kind":"dialogue"},{"uid":"talk.ch18_5_3127#originalText","id":"talk.ch18_5_3127","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"那个……亚丝娜大人？请问这两位是……","en":"Um...Lady Asuna? Who exactly are these people?","ja":"あの……アスナ様?その方たちはいったい……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3128#originalText","id":"talk.ch18_5_3128","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"还有那些骑士们……","en":"And also, those knights...","ja":"それに、あの騎士たちは……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3129#originalText","id":"talk.ch18_5_3129","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"他们是我重要的伙伴们，是从现实世界来帮我们的。","en":"They're my precious friends. They've come from the real world to help us.","ja":"わたしの大切な仲間たちリアルワールドから、助けに来てくれたの"},"kind":"dialogue"},{"uid":"talk.ch18_5_3130#originalText","id":"talk.ch18_5_3130","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"原来是这样……真是太好了……","en":"Is that right? I'm so glad.","ja":"そうだったんですか……ほんとによかった……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3131#originalText","id":"talk.ch18_5_3131","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我还以为外面世界的人类，除了亚丝娜大人以外全都是那种可怕的士兵……","en":"I thought that everyone from the outside world, aside from you, was scary, like those soldiers.","ja":"僕はてっきり、外の世界の人間たちは、アスナ様以外はみんなあんな恐ろしい兵士なのかと"},"kind":"dialogue"},{"uid":"talk.ch18_5_3132#originalText","id":"talk.ch18_5_3132","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂喂，那怎么可能啊！！","en":"Whoa, whoa, of course we're not like that!","ja":"ちょっとちょっと、そんなわけないじゃん!!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3133#originalText","id":"talk.ch18_5_3133","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我叫莉兹贝特。请多指教，骑士弟弟。","en":"I'm Lisbeth. Nice to meet you, Mr. Knight.","ja":"あたしリズベットよろしくね、騎士くん"},"kind":"dialogue"},{"uid":"talk.ch18_5_3134#originalText","id":"talk.ch18_5_3134","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊……好、好的。初次见面，我叫连利。","en":"Uh...right! Nice to meet you. My name is Renly.","ja":"あ……は、はいはじめまして、僕はレンリといいます"},"kind":"dialogue"},{"uid":"talk.ch18_5_3135#originalText","id":"talk.ch18_5_3135","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹，转移过来的共有多少人？","en":"Liz, how many people converted in all?","ja":"リズ、コンバートしてくれた人たちの数は?"},"kind":"dialogue"},{"uid":"talk.ch18_5_3136#originalText","id":"talk.ch18_5_3136","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"啊……嗯，大概两千再多一点吧。","en":"Um, maybe a little over two thousand, I think.","ja":"あ……うん2000を少し超えるくらい、かな"},"kind":"dialogue"},{"uid":"talk.ch18_5_3137#originalText","id":"talk.ch18_5_3137","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然我努力劝过了……但不是所有听过说明的人都愿意转移……","en":"I did my best, but I couldn't convince every single player who heard me out.","ja":"がんばったんだけど……話を聞いてくれた人たち全員ってわけにはいかなかった……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3138#originalText","id":"talk.ch18_5_3138","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这样已经很够了。","en":"That's more than enough.","ja":"充分すぎるわ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3139#originalText","id":"talk.ch18_5_3139","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"可是……为了之后能再转移回去，应该避免消耗战。","en":"But to keep reconverting a possibility, I'd like to avoid a war of attrition.","ja":"でも……再コンバートの可能性を残すためにも消耗戦は避けたい"},"kind":"dialogue"},{"uid":"talk.ch18_5_3140#originalText","id":"talk.ch18_5_3140","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"别将前线战场扩得太大，增加补师的人数吧！","en":"Let's not expand the front lines too much, and bolster our healing.","ja":"あまり前線を広げないで、ヒールを厚くしよう"},"kind":"dialogue"},{"uid":"talk.ch18_5_3141#originalText","id":"talk.ch18_5_3141","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹和西莉卡带着两百人退到后方创建支持部队。","en":"Liz, Silica, I want you to fall back with 200 or so and form a support unit.","ja":"リズとシリカちゃんは、200人くらい後方に下げて支援部隊を作って"},"kind":"dialogue"},{"uid":"talk.ch18_5_3142#originalText","id":"talk.ch18_5_3142","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"连利先生，虽然各位应该有别的打算，但还是请你们跟修士队会合，使用治愈术吧。","en":"I know this isn't what you want to hear, but please join the monks and use your healing arts.","ja":"レンリさん、皆さんも不本意でしょうが修道士隊に合流して、治癒術を使ってください"},"kind":"dialogue"},{"uid":"talk.ch18_5_3143#originalText","id":"talk.ch18_5_3143","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"现实世界的剑士们不熟悉神圣术──","en":"Since the real-world swordsmen aren't familiar with the Sacred Arts...","ja":"リアルワールドの剣士たちは神聖術に不慣れなので――"},"kind":"dialogue"},{"uid":"talk.ch18_5_3144#originalText","id":"talk.ch18_5_3144","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要是你们愿意教导他们术式，就能帮我很大的忙。","en":"...it would really help if you could teach them the formal arts.","ja":"彼らに術式を教えてやってくださると助かります"},"kind":"dialogue"},{"uid":"talk.ch18_5_3145#originalText","id":"talk.ch18_5_3145","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"好……好的，亚丝娜大人！","en":"Uh, right, Lady Asuna!","ja":"は……はい、アスナ様!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3146#originalText","id":"talk.ch18_5_3146","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"侍卫队，正如你们所听见的！我们要支持援军的众骑士！","en":"You heard her! We're going to support those reinforcement knights!","ja":"衛士隊、聞いてのとおりだ!援軍の騎士たちを支援するぞ!"},"kind":"dialogue"},{"uid":"talk.ch18_5_3147#originalText","id":"talk.ch18_5_3147","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那么……亚丝娜有什么打算呢？","en":"And...what are you going to do, Asuna?","ja":"……それで、アスナさんはどうするんですか?"},"kind":"dialogue"},{"uid":"talk.ch18_5_3148#originalText","id":"talk.ch18_5_3148","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"当然是在最前线杀敌喽！","en":"I will fight at the front, of course!","ja":"もちろん、いちばん前に斬り込むわよ"},"kind":"dialogue"},{"uid":"talk.ch18_5_3149#originalText","id":"talk.ch18_5_3149","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我已经不会再输了，只要有大家在……","en":"Now we won't lose. Now that everyone's here.","ja":"もう、負けないみんながいれば……"},"kind":"dialogue"},{"uid":"talk.ch18_5_3150#originalText","id":"talk.ch18_5_3150","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大家同心协力，绝对能赢！","en":"All together, we can definitely win!","ja":"みんななら、絶対に勝てる!"},"kind":"dialogue"}]};
